// Simulating NestJS decorators and patterns
function Module(metadata) {
  return function(target) {
    target.__module = metadata;
    return target;
  };
}

function Controller(prefix) {
  return function(target) {
    target.__controller = { prefix };
    return target;
  };
}

function Injectable() {
  return function(target) {
    target.__injectable = true;
    return target;
  };
}

function Inject(token) {
  return function(target, propertyKey, parameterIndex) {
    if (!target.__inject) target.__inject = [];
    target.__inject[parameterIndex] = token;
  };
}

function Get(path) {
  return function(target, propertyKey) {
    if (!target.__routes) target.__routes = [];
    target.__routes.push({ method: 'GET', path, handler: propertyKey });
  };
}

function Post(path) {
  return function(target, propertyKey) {
    if (!target.__routes) target.__routes = [];
    target.__routes.push({ method: 'POST', path, handler: propertyKey });
  };
}

// === MODULE: Users ===

@Injectable()
class UsersService {
  private users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' }
  ];

  findAll() {
    return this.users;
  }

  findById(id) {
    return this.users.find(u => u.id === id);
  }

  create(userData) {
    const user = { id: this.users.length + 1, ...userData };
    this.users.push(user);
    return user;
  }
}

@Controller('/users')
class UsersController {
  constructor(@Inject('UsersService') private usersService) {
    this.usersService = new UsersService();
  }

  @Get('/')
  findAll() {
    return this.usersService.findAll();
  }

  @Get('/:id')
  findById(req) {
    return this.usersService.findById(parseInt(req.params.id));
  }

  @Post('/')
  create(req) {
    return this.usersService.create(req.body);
  }
}

@Module({
  controllers: [UsersController],
  providers: [UsersService],
  exports: [UsersService]
})
class UsersModule {}

// === MODULE: Auth ===

@Injectable()
class AuthService {
  validateUser(email, password) {
    // Simplified auth
    return email.includes('@') && password.length >= 6;
  }

  generateToken(user) {
    return 'jwt-token-' + user.id;
  }
}

@Injectable()
class JwtGuard {
  canActivate(req) {
    const token = req.headers?.authorization;
    return token && token.startsWith('Bearer ');
  }
}

@Module({
  providers: [AuthService, JwtGuard],
  exports: [AuthService, JwtGuard]
})
class AuthModule {}

// === APP MODULE ===

@Module({
  imports: [AuthModule, UsersModule],
  providers: []
})
class AppModule {}

